// The Cart on the device (Req 12.1 to 12.9): a nanostore over the stored guest Cart_Token and line snapshots.
// Prices and totals always come from the Store_API; the browser sends no amount (Req 21.5).
import { atom } from 'nanostores';
import { createStoreApi, StoreApiError, type StoreApi } from '../store-api';
import { clearCart, getCart, getItem, getJson, setCart, type StoredCart, type StoredCartLine } from '../storage';
import { currentAccessToken, getSession } from '../auth/session';
import { notifyCartChanged } from '../cart-count';
import catalogMeta from '../../data/catalog.json';
import deliveryRules from '../../data/delivery-rules.json';

type Obj = Record<string, unknown>;
const obj = (v: unknown): Obj => (v && typeof v === 'object' && !Array.isArray(v) ? (v as Obj) : {});
const num = (v: unknown): number | null => (typeof v === 'number' && Number.isFinite(v) ? v : typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v)) ? Number(v) : null);
const text = (v: unknown): string => (typeof v === 'string' ? v : '');

export const QTY_DELAY_MS = 400;
export const UNDO_MS = 10_000;

export interface CartLine {
  id: string;
  productId: string;
  variantId: string;
  title: string;
  variantTitle: string;
  handle: string;
  thumbnail: string | null;
  qty: number;
  unitPrice: number;
  compareAt: number | null;
  total: number;
  /** Price or quantity differs from what the shopper last saw (Req 12.4). */
  changed: boolean;
  /** Not available any more: checkout stays disabled until the line is removed (Req 12.5). */
  unavailable: boolean;
}

export interface CartTotals {
  subtotal: number;
  discount: number;
  /** null until a delivery option is chosen. */
  shipping: number | null;
  tax: number;
  total: number;
  /** Items after discounts: the amount that counts toward free delivery. */
  itemTotal: number;
}

export interface UndoInfo { title: string; productId: string; variantId: string; qty: number }

export interface CartState {
  status: 'idle' | 'loading' | 'ready' | 'error';
  lines: CartLine[];
  totals: CartTotals;
  currency: string;
  codes: string[];
  /** Error code of the last failed action, or ''. */
  error: string;
  /** Short message key of the last result. */
  notice: { key: string; params?: Record<string, string> } | null;
  undo: UndoInfo | null;
  freeDeliveryThreshold: number | null;
  /** Result of the delivery preview for a PIN code. */
  preview: { pin: string; shipping: number | null; serviceable: boolean } | null;
  busy: boolean;
}

const emptyTotals: CartTotals = { subtotal: 0, discount: 0, shipping: null, tax: 0, total: 0, itemTotal: 0 };
const threshold = num((deliveryRules as Obj).free_delivery_threshold);

export const $cart = atom<CartState>({
  status: 'idle', lines: [], totals: emptyTotals, currency: 'INR', codes: [], error: '', notice: null, undo: null,
  freeDeliveryThreshold: threshold, preview: null, busy: false,
});

const set = (patch: Partial<CartState>): void => $cart.set({ ...$cart.get(), ...patch });

let apiInstance: StoreApi | null = null;
const api = (): StoreApi => (apiInstance ??= createStoreApi({ getAccessToken: () => currentAccessToken() }));

const codeOf = (e: unknown): string => (e instanceof StoreApiError ? e.code : 'internal_error');

// --- View mapping -----------------------------------------------------------------------------------------------------

/** Maps a Store_API cart view; `previous` are the snapshots the shopper last saw (null: nothing to compare). */
export function mapView(view: unknown, previous: Record<string, StoredCartLine> | null): { lines: CartLine[]; totals: CartTotals; currency: string } {
  const v = obj(view);
  const lines: CartLine[] = (Array.isArray(v.items) ? v.items : []).map((raw) => {
    const i = obj(raw);
    const id = text(i.id);
    const qty = num(i.quantity) ?? 0;
    const unitPrice = num(i.unit_price) ?? 0;
    const was = previous?.[id];
    return {
      id, qty, unitPrice,
      productId: text(i.product_id), variantId: text(i.variant_id),
      title: text(i.product_title) || text(i.title), variantTitle: text(i.variant_title), handle: text(i.product_handle),
      thumbnail: text(i.thumbnail) || null,
      compareAt: num(i.compare_at_unit_price),
      total: num(i.total) ?? unitPrice * qty,
      changed: !!was && (was.price !== unitPrice || was.qty !== qty),
      unavailable: false,
    };
  });
  const shippingMethods = Array.isArray(v.shipping_methods) ? v.shipping_methods : [];
  return {
    lines,
    currency: (text(v.currency_code) || 'inr').toUpperCase(),
    totals: {
      subtotal: num(v.original_item_total) ?? num(v.item_total) ?? 0,
      discount: num(v.discount_total) ?? 0,
      shipping: shippingMethods.length ? (num(v.shipping_total) ?? 0) : null,
      tax: num(v.tax_total) ?? 0,
      total: num(v.total) ?? 0,
      itemTotal: num(v.item_total) ?? 0,
    },
  };
}

function snapshots(lines: CartLine[]): Record<string, StoredCartLine> {
  return Object.fromEntries(lines.map((l) => [l.id, {
    price: l.unitPrice, qty: l.qty, available: !l.unavailable, variantId: l.variantId, productId: l.productId,
    title: l.title, variantTitle: l.variantTitle, handle: l.handle, thumbnail: l.thumbnail,
  }]));
}

function persist(lines: CartLine[]): void {
  const c = getCart();
  if (!c) return;
  setCart({ ...c, lines: snapshots(lines) });
  notifyCartChanged();
}

/** Lines that the last Live_Data answer says are gone (product or variant no longer sold). */
export function markUnavailable(lines: CartLine[], live: unknown): CartLine[] {
  const products = Array.isArray(obj(live).products) ? (obj(live).products as unknown[]).map(obj) : [];
  return lines.map((l) => {
    const p = products.find((x) => x.id === l.productId);
    if (!p) return l;
    const variant = (Array.isArray(p.variants) ? p.variants : []).map(obj).find((x) => x.id === l.variantId);
    const gone = p.available === false || (variant !== undefined && (variant.available === false || variant.sellable === false || variant.in_stock === false));
    return gone ? { ...l, unavailable: true } : l;
  });
}

function apply(view: unknown, opts: { compare?: boolean; live?: unknown } = {}): void {
  const stored = getCart();
  const mapped = mapView(view, opts.compare ? (stored?.lines ?? null) : null);
  const prev = $cart.get().lines;
  // A line that was unavailable stays marked until Live_Data says otherwise.
  const lines = markUnavailable(mapped.lines, opts.live).map((l) => (opts.live === undefined && prev.find((p) => p.id === l.id)?.unavailable ? { ...l, unavailable: true } : l));
  set({ status: 'ready', lines, totals: mapped.totals, currency: mapped.currency, error: '' });
  persist(lines);
}

// --- Cart session -----------------------------------------------------------------------------------------------------

async function regionId(): Promise<string | null> {
  const known = text((catalogMeta as Obj).region_id) || text((deliveryRules as Obj).region_id);
  if (known) return known;
  try {
    return text(obj(await api().call('store_delivery_rules')).region_id) || null;
  } catch {
    return null;
  }
}

/** A signed-in Customer's device hands its guest Cart over once (Req 12.8). Returns true when the Cart changed. */
export async function transferIfSignedIn(): Promise<boolean> {
  const stored = getCart();
  if (!stored || !stored.token || !getSession() || !currentAccessToken()) return false;
  try {
    const r = obj(await api().call('store_cart_transfer', { p_cart_id: stored.id, p_cart_token: stored.token }));
    const cart = obj(r.cart);
    if (!text(cart.id)) return false;
    // The Customer's own Cart needs no Cart_Token: the session proves ownership.
    setCart({ id: text(cart.id), token: '' });
    apply(cart);
    if (Array.isArray(r.not_merged) && r.not_merged.length) set({ notice: { key: 'notMerged' } });
    return true;
  } catch (e) {
    if (e instanceof StoreApiError && e.code === 'not_found') clearCart();
    return false;
  }
}

async function ensureCart(): Promise<void> {
  await transferIfSignedIn();
  if (getCart()) return;
  const region = await regionId();
  if (!region) throw new StoreApiError({ code: 'validation_failed', status: 400, message: 'No region' });
  const r = obj(await api().call('store_create_cart', { p_region_id: region }));
  const cart = obj(r.cart);
  if (!text(cart.id)) throw new StoreApiError({ code: 'internal_error', status: 500 });
  setCart({ id: text(cart.id), token: text(r.cart_token) });
}

function fail(e: unknown): void {
  const code = codeOf(e);
  set({ error: code, busy: false });
}

async function run(fn: () => Promise<unknown>): Promise<boolean> {
  set({ busy: true, error: '' });
  try {
    apply(obj(await fn()).cart);
    set({ busy: false });
    return true;
  } catch (e) {
    fail(e);
    return false;
  }
}

const cartArgs = () => ({});

/** Reads the Cart again; marks lines that changed since the shopper last saw them (Req 12.4). */
export async function loadCart(): Promise<void> {
  const stored = getCart();
  if (!stored) {
    set({ status: 'ready', lines: [], totals: emptyTotals });
    return;
  }
  // Show the line snapshots from the device at once, then confirm them.
  if ($cart.get().status === 'idle' && stored.lines) {
    const lines: CartLine[] = Object.entries(stored.lines).map(([id, s]) => ({
      id, qty: s.qty ?? 0, unitPrice: s.price ?? 0, productId: s.productId ?? '', variantId: s.variantId ?? '', title: s.title ?? '',
      variantTitle: s.variantTitle ?? '', handle: s.handle ?? '', thumbnail: s.thumbnail ?? null, compareAt: null,
      total: (s.price ?? 0) * (s.qty ?? 0), changed: false, unavailable: s.available === false,
    }));
    set({ status: 'loading', lines });
  } else set({ status: 'loading' });
  await transferIfSignedIn();
  try {
    const view = obj(await api().cartCall('store_get_cart', cartArgs())).cart;
    const ids = [...new Set(mapView(view, null).lines.map((l) => l.productId).filter(Boolean))];
    let live: unknown;
    if (ids.length) {
      try {
        live = await api().call('store_live_data', { p_product_ids: `{${ids.map((i) => `"${i}"`).join(',')}}`, p_region_id: text((catalogMeta as Obj).region_id) || undefined });
      } catch {
        live = undefined;
      }
    }
    apply(view, { compare: true, live });
  } catch (e) {
    if (getCart() === null) set({ status: 'ready', lines: [], totals: emptyTotals });
    else set({ status: 'error', error: codeOf(e) });
  }
}

export async function addItem(productId: string, variantId: string, qty = 1): Promise<boolean> {
  set({ busy: true, error: '', notice: null });
  try {
    await ensureCart();
    const ok = await run(() => api().cartCall('store_cart_add_item', { p_variant_id: variantId, p_quantity: qty }));
    if (ok) set({ notice: { key: 'added' } });
    void productId;
    return ok;
  } catch (e) {
    fail(e);
    return false;
  }
}

// --- Quantity changes: sent 400 ms after the last tap (Req 12.3) ---------------------------------------------------------

const qtyTimers = new Map<string, ReturnType<typeof setTimeout>>();

export function setQty(lineId: string, qty: number): void {
  const s = $cart.get();
  if (qty < 1) return void removeLine(lineId);
  const lines = s.lines.map((l) => (l.id === lineId ? { ...l, qty, total: l.unitPrice * qty } : l));
  set({ lines });
  clearTimeout(qtyTimers.get(lineId));
  qtyTimers.set(lineId, setTimeout(() => {
    qtyTimers.delete(lineId);
    const q = $cart.get().lines.find((l) => l.id === lineId)?.qty ?? qty;
    void run(() => api().cartCall('store_cart_update_item', { p_line_item_id: lineId, p_quantity: q })).then((ok) => {
      if (!ok) void loadCart();
    });
  }, QTY_DELAY_MS));
}

// --- Removal with undo for 10 seconds (Req 12.6) ------------------------------------------------------------------------

let undoTimer: ReturnType<typeof setTimeout> | undefined;

export async function removeLine(lineId: string): Promise<void> {
  const line = $cart.get().lines.find((l) => l.id === lineId);
  if (!line) return;
  clearTimeout(qtyTimers.get(lineId));
  qtyTimers.delete(lineId);
  set({ lines: $cart.get().lines.filter((l) => l.id !== lineId) });
  const ok = await run(() => api().cartCall('store_cart_remove_item', { p_line_item_id: lineId }));
  if (!ok) return void loadCart();
  clearTimeout(undoTimer);
  set({ undo: { title: line.title, productId: line.productId, variantId: line.variantId, qty: line.qty } });
  undoTimer = setTimeout(() => set({ undo: null }), UNDO_MS);
}

export async function undoRemove(): Promise<void> {
  const u = $cart.get().undo;
  if (!u) return;
  clearTimeout(undoTimer);
  set({ undo: null });
  await addItem(u.productId, u.variantId, u.qty);
}

// --- Promotion code, Wishlist, delivery preview ---------------------------------------------------------------------------

export async function applyCode(code: string): Promise<boolean> {
  const c = code.trim();
  if (!c) return false;
  const ok = await run(() => api().cartCall('store_cart_apply_code', { p_code: c }));
  if (ok) set({ codes: [...new Set([...$cart.get().codes, c.toUpperCase()])], notice: { key: 'promoApplied', params: { code: c.toUpperCase() } } });
  return ok;
}

export async function removeCode(code: string): Promise<void> {
  const ok = await run(() => api().cartCall('store_cart_remove_code', { p_code: code }));
  if (ok) set({ codes: $cart.get().codes.filter((x) => x !== code) });
}

/** Adds the product to the Wishlist, then takes the line out of the Cart (Req 12.7). Needs a signed-in Customer. */
export async function moveToWishlist(lineId: string): Promise<void> {
  const line = $cart.get().lines.find((l) => l.id === lineId);
  if (!line) return;
  if (!currentAccessToken()) return set({ notice: { key: 'signInWishlist' } });
  try {
    await api().call('store_add_to_wishlist', { p_product_id: line.productId, p_variant_id: line.variantId });
  } catch (e) {
    return fail(e);
  }
  const ok = await run(() => api().cartCall('store_cart_remove_item', { p_line_item_id: lineId }));
  if (ok) set({ notice: { key: 'movedToWishlist', params: { title: line.title } } });
}

/** The PIN code the shopper entered on the PDP or at checkout, when it is on the device. */
export function rememberedPin(): string {
  const raw = getJson<unknown>('sf.pin');
  const v = typeof raw === 'string' ? raw : obj(raw).pin ?? obj(raw).code ?? getItem('sf.pin') ?? '';
  const s = text(v);
  return /^[1-9]\d{5}$/.test(s) ? s : '';
}

/** Delivery charge for a PIN code without changing the address (Req 12.2). */
export async function previewDelivery(pin: string): Promise<void> {
  set({ busy: true, error: '' });
  try {
    const r = obj(await api().cartCall('store_cart_delivery_preview', { p_postal_code: pin }));
    const ship = num(r.shipping_total);
    set({ busy: false, preview: { pin, serviceable: r.serviceable === true, shipping: ship } });
  } catch (e) {
    fail(e);
  }
}

/** Test hook: forget the module's timers and the cached client. */
export function resetCartForTests(): void {
  for (const t of qtyTimers.values()) clearTimeout(t);
  qtyTimers.clear();
  clearTimeout(undoTimer);
  apiInstance = null;
  $cart.set({ ...$cart.get(), status: 'idle', lines: [], totals: emptyTotals, undo: null, error: '', notice: null, codes: [], preview: null, busy: false });
}

export type { StoredCart };
