// Supabase Auth over its REST API (sign-up, sign-in, password reset, sign-out) with the Turnstile
// captcha token (Req 14.7), and the session kept in `sf.auth` until sign-out (Req 14.9).
import { getJson, removeItem, setJson } from '../storage';

export interface AuthSession {
  access_token: string;
  refresh_token: string;
  /** Seconds since the epoch. */
  expires_at: number;
  user: { id: string; email: string | null };
}

export type AuthErrorCode = 'invalid_credentials' | 'email_not_confirmed' | 'weak_password' | 'captcha_failed' | 'rate_limited' | 'user_exists' | 'network_error' | 'unknown';

export class AuthError extends Error {
  constructor(readonly code: AuthErrorCode, readonly status: number, message?: string) {
    super(message ?? code);
    this.name = 'AuthError';
  }
}

export interface AuthConfig {
  url: string;
  key: string;
  fetch?: typeof fetch;
  now?: () => number;
}

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

export function mapAuthError(status: number, body: unknown): AuthError {
  const b = isObj(body) ? body : {};
  const code = String(b.error_code ?? b.code ?? '');
  const msg = String(b.msg ?? b.message ?? b.error_description ?? '');
  if (status === 429 || code === 'over_request_rate_limit' || code === 'over_email_send_rate_limit') return new AuthError('rate_limited', status, msg);
  if (/captcha/i.test(code) || /captcha/i.test(msg)) return new AuthError('captcha_failed', status, msg);
  if (code === 'invalid_credentials' || /invalid login/i.test(msg)) return new AuthError('invalid_credentials', status, msg);
  if (code === 'email_not_confirmed' || /not confirmed/i.test(msg)) return new AuthError('email_not_confirmed', status, msg);
  if (code === 'weak_password') return new AuthError('weak_password', status, msg);
  if (code === 'user_already_exists' || code === 'email_exists') return new AuthError('user_exists', status, msg);
  return new AuthError('unknown', status, msg);
}

/** Reads a session out of a token response, or null when it carries none. */
export function toSession(body: unknown, now = Date.now()): AuthSession | null {
  if (!isObj(body) || typeof body.access_token !== 'string' || typeof body.refresh_token !== 'string') return null;
  const user = isObj(body.user) ? body.user : {};
  const expiresIn = typeof body.expires_in === 'number' ? body.expires_in : 3600;
  const expiresAt = typeof body.expires_at === 'number' ? body.expires_at : Math.floor(now / 1000) + expiresIn;
  return {
    access_token: body.access_token,
    refresh_token: body.refresh_token,
    expires_at: expiresAt,
    user: { id: String(user.id ?? ''), email: typeof user.email === 'string' ? user.email : null },
  };
}

export function createAuth(cfg: AuthConfig) {
  const base = cfg.url.replace(/\/+$/, '');
  const doFetch = () => cfg.fetch ?? globalThis.fetch;
  const nowMs = () => (cfg.now ?? Date.now)();

  async function request(path: string, init: { method?: string; body?: unknown; token?: string } = {}): Promise<unknown> {
    let res: Response;
    try {
      res = await doFetch()(`${base}/auth/v1${path}`, {
        method: init.method ?? 'POST',
        headers: { apikey: cfg.key, Authorization: `Bearer ${init.token ?? cfg.key}`, 'Content-Type': 'application/json' },
        body: init.body === undefined ? undefined : JSON.stringify(init.body),
      });
    } catch {
      throw new AuthError('network_error', 0);
    }
    const text = await res.text().catch(() => '');
    let body: unknown = null;
    try {
      body = text ? JSON.parse(text) : null;
    } catch {
      body = null;
    }
    if (!res.ok) throw mapAuthError(res.status, body);
    return body;
  }

  const captcha = (token: string | undefined) => (token ? { gotrue_meta_security: { captcha_token: token } } : {});

  function store(s: AuthSession | null): AuthSession | null {
    if (s) setJson('sf.auth', s);
    return s;
  }

  return {
    /** Returns the session when sign-up signs the Customer in; null when the email must be confirmed first. */
    async signUp(email: string, password: string, captchaToken?: string, language?: string): Promise<AuthSession | null> {
      const body = await request('/signup', { body: { email, password, data: language ? { language } : undefined, ...captcha(captchaToken) } });
      return store(toSession(body, nowMs()));
    },
    async signIn(email: string, password: string, captchaToken?: string): Promise<AuthSession> {
      const body = await request('/token?grant_type=password', { body: { email, password, ...captcha(captchaToken) } });
      const s = toSession(body, nowMs());
      if (!s) throw new AuthError('unknown', 200);
      store(s);
      return s;
    },
    async requestReset(email: string, redirectTo: string, captchaToken?: string): Promise<void> {
      await request(`/recover?redirect_to=${encodeURIComponent(redirectTo)}`, { body: { email, ...captcha(captchaToken) } });
    },
    /** Sets a new password with the recovery session from the emailed link. */
    async updatePassword(accessToken: string, password: string): Promise<void> {
      await request('/user', { method: 'PUT', token: accessToken, body: { password } });
    },
    async refresh(s: AuthSession): Promise<AuthSession> {
      const body = await request('/token?grant_type=refresh_token', { body: { refresh_token: s.refresh_token } });
      const next = toSession(body, nowMs());
      if (!next) throw new AuthError('unknown', 200);
      store(next);
      return next;
    },
    async logout(s: AuthSession): Promise<void> {
      try {
        await request('/logout', { token: s.access_token });
      } catch {
        /* the device is cleared either way */
      }
    },
  };
}

export type Auth = ReturnType<typeof createAuth>;

export function getSession(): AuthSession | null {
  const s = getJson<AuthSession>('sf.auth');
  return s && typeof s.access_token === 'string' && typeof s.refresh_token === 'string' ? s : null;
}

/** The stored session when it is still valid for at least a minute. */
export function currentAccessToken(now = Date.now()): string | null {
  const s = getSession();
  return s && s.expires_at * 1000 - now > 60_000 ? s.access_token : null;
}

/** The stored session, refreshed when it is about to expire; null (and cleared) when it cannot be. */
export async function ensureSession(auth: Auth, now = Date.now()): Promise<AuthSession | null> {
  const s = getSession();
  if (!s) return null;
  if (s.expires_at * 1000 - now > 60_000) return s;
  try {
    return await auth.refresh(s);
  } catch (e) {
    if (e instanceof AuthError && e.code !== 'network_error') removeItem('sf.auth');
    return null;
  }
}

/**
 * Sign-out: removes the session, the loaded account data and the reference to the Customer's Cart
 * from the device (Req 14.9). The guest order token goes too, so the next visitor sees nothing.
 */
export function clearDevice(): void {
  for (const k of ['sf.auth', 'sf.cart', 'sf.order']) removeItem(k);
}

/** Reads `#access_token=…&type=recovery` from a password-reset link. */
export function parseRecoveryHash(hash: string): { accessToken: string } | null {
  const p = new URLSearchParams(hash.replace(/^#/, ''));
  const token = p.get('access_token');
  return p.get('type') === 'recovery' && token ? { accessToken: token } : null;
}
